def match(orders):
    import heapq

    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    order_info = {}  # id -> {'side':..., 'price':..., 'qty':..., 'active':bool, 'resting':bool}
    seq_counter = 0
    trades = []

    def add_resting(id_, side, price, seq):
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            _, cid = order
            info = order_info.get(cid)
            if info and info.get('resting') and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, id_, side, price, qty = order
        elif typ == 'ioc':
            _, id_, side, price, qty = order
        else:  # market
            _, id_, side, qty = order
            price = None

        seq_counter += 1
        seq = seq_counter
        remaining = qty

        order_info[id_] = {'side': side, 'price': price, 'qty': qty, 'active': True, 'resting': False}

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                top_price = top[0]
            else:
                top_price = -top[0]
            top_id = top[2]
            top_info = order_info.get(top_id)

            if top_info is None or (not top_info['active']) or top_info['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, top_info['qty'])
            trade_price = top_price

            if side == 'buy':
                trades.append([id_, top_id, trade_price, trade_qty])
            else:
                trades.append([top_id, id_, trade_price, trade_qty])

            remaining -= trade_qty
            top_info['qty'] -= trade_qty

            if top_info['qty'] == 0:
                top_info['active'] = False
                heapq.heappop(opp_heap)

        order_info[id_]['qty'] = remaining

        if typ == 'limit':
            if remaining > 0:
                order_info[id_]['resting'] = True
                order_info[id_]['active'] = True
                add_resting(id_, side, price, seq)
            else:
                order_info[id_]['resting'] = False
                order_info[id_]['active'] = False
        else:
            # ioc or market: remainder discarded, never rests
            order_info[id_]['resting'] = False
            order_info[id_]['active'] = False

    return trades

